# typed: strict
# frozen_string_literal: true

# Generated by scripts/release/package_metadata.py. Do not edit.
class Devknx < Formula
  desc "KNX monitor with CLI, TUI, GUI, REST and MCP"
  homepage "https://github.com/metaneutrons/devknx"
  license "GPL-3.0-only"

  on_macos do
    depends_on arch: :arm64
    on_arm do
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.0/devknx-v0.4.0-aarch64-apple-darwin.tar.gz"
      sha256 "6137c4022db30126d2c48133075e9c720b5b74d3347ee358551eb0e0dc0b9a2a"
    end
  end

  on_linux do
    depends_on "libx11"
    depends_on "libxcb"
    depends_on "libxcursor"
    depends_on "libxi"
    depends_on "libxkbcommon"
    depends_on "mesa"
    depends_on "wayland"
    if Hardware::CPU.arm?
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.0/devknx-v0.4.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "109f867f4b2c94a1731eae6cfa1cc3a561fc198e7638743a9fac19afc05ecc87"
    else
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.0/devknx-v0.4.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "250a9a7bb14012b148134f1fec5ae11f62b97c58a4c53f9928c2c9ee33884f24"
    end
  end

  def install
    root = Dir["devknx", "devknx-v*-*/devknx"].find { |path| File.file?(path) }
    raise "missing devknx executable" unless root

    if OS.linux?
      libexec.install root
      gui_libraries = %w[
        libx11 libxcb libxcursor libxi libxkbcommon mesa wayland
      ].map { |name| formula_opt_lib(name) }
      loader_path = "#{gui_libraries.join(":")}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
      bin.join("devknx").write_env_script libexec/"devknx", LD_LIBRARY_PATH: loader_path
    else
      bin.install root
    end
    source_root = File.dirname(root)
    doc.install File.join(source_root, "THIRD-PARTY-NOTICES.md")
    doc.install File.join(source_root, "licenses")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/devknx --version")
  end
end
